"""LDA pipeline with imputation and scaling."""

from sklearn.compose import ColumnTransformer
from sklearn.impute import SimpleImputer
from sklearn.pipeline import Pipeline
from sklearn.preprocessing import StandardScaler
from sklearn.discriminant_analysis import LinearDiscriminantAnalysis


def build_pipeline(profile: dict):
    # select numeric feature columns, excluding non‑feature identifiers like "Id"
    feature_names = [
        col["name"]
        for col in profile.get("columns", [])
        if col["name"] != "Id" and col["kind"] == "numeric"
    ]

    # preprocessing: median imputation then standard scaling
    preprocess = ColumnTransformer(
        [
            (
                "num",
                Pipeline(
                    [
                        ("impute", SimpleImputer(strategy="median")),
                        ("scale", StandardScaler()),
                    ]
                ),
                feature_names,
            )
        ],
        remainder="drop",
    )

    # choose model based on problem type
    if profile.get("problem_type") == "regression":
        from sklearn.linear_model import LinearRegression

        model = LinearRegression()
    else:
        model = LinearDiscriminantAnalysis()

    return Pipeline([("preprocess", preprocess), ("model", model)])

